<section class="panel upload-panel"><div><h2>Install a theme</h2><p>Upload a trusted AfiuCMS ZIP with <code>theme.json</code> at its root.</p><small class="danger-text">Theme PHP files execute server-side code. Only install packages you trust.</small></div><form class="upload-form" method="post" action="/admin/themes/upload" enctype="multipart/form-data"><?= csrf_field() ?><input type="file" name="theme" accept=".zip,application/zip" required><button class="btn" type="submit">Install ZIP</button></form></section><div class="theme-grid modern"><?php foreach($themes as $theme):?><article class="theme-card <?= !empty($theme['active'])?'active-theme':'' ?>"><div class="theme-shot"><img src="/theme-assets/<?= e($theme['slug']) ?>/preview.svg" alt="<?= e($theme['name']) ?> preview" onerror="this.style.display='none'"><?php if(!empty($theme['active'])):?><span class="active-ribbon">Active</span><?php endif;?></div><div class="theme-body"><div><h3><?= e($theme['name']) ?></h3><p><?= e($theme['description']??'') ?></p></div><div class="theme-meta"><span>v<?= e($theme['version']) ?></span><span><?= e($theme['author']??'Unknown') ?></span></div><?php if(empty($theme['active'])):?><form method="post" action="/admin/themes/<?= e($theme['slug']) ?>/activate"><?= csrf_field() ?><button class="btn primary wide" type="submit">Activate theme</button></form><?php else:?><a class="btn ghost wide" href="/" target="_blank">View active site ↗</a><?php endif;?></div></article><?php endforeach;?></div>